using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Text;
namespace VinsPDF {
internal static class TextParagraphs {
 public static List<EditObject> Group(List<EditObject> lines,SizeF page,bool enabled){if(!enabled)return lines;var result=new List<EditObject>();var used=new HashSet<EditObject>();foreach(var group in lines.Where(o=>o.Kind==1&&o.BlockKey!=null).GroupBy(o=>o.BlockKey)){float angle=group.First().Angle;var block=group.OrderBy(o=>Along(o,page,angle)).ToList();result.Add(Combine(block,page));foreach(var o in block)used.Add(o);}var candidates=lines.Where(o=>!used.Contains(o)&&o.Kind==1&&Math.Abs(o.Angle)<3&&!o.Locked).OrderBy(o=>o.Bounds.Top).ThenBy(o=>o.Bounds.Left).ToList();foreach(var first in candidates){if(used.Contains(first))continue;var block=new List<EditObject>{first};var last=first;while(true){float font=Math.Max(1,last.DisplayFontSize);var next=candidates.Where(o=>!used.Contains(o)&&!block.Contains(o)&&o.Layer==first.Layer&&o.Color==first.Color&&Math.Abs(o.DisplayFontSize-first.DisplayFontSize)<font*.08f&&o.BaselineY>last.BaselineY&&(o.BaselineY-last.BaselineY)*page.Height>=font*.85f&&(o.BaselineY-last.BaselineY)*page.Height<=font*3.4f&&Math.Abs(o.Bounds.Left-first.Bounds.Left)*page.Width<=font*.8f&&o.Bounds.Width*page.Width>font*4&&last.Bounds.Width*page.Width>font*4).OrderBy(o=>o.BaselineY).ThenBy(o=>Math.Abs(o.Bounds.Left-first.Bounds.Left)).FirstOrDefault();if(next==null)break;block.Add(next);last=next;}if(block.Count>=2&&block.Sum(o=>o.Text.Length)>=70&&block.Count(o=>o.Text.Count(char.IsWhiteSpace)>=3)>=2){result.Add(Combine(block,page));foreach(var o in block)used.Add(o);}}result.AddRange(lines.Where(o=>!used.Contains(o)));return result;}
 static float Along(EditObject o,SizeF page,float angle){double a=angle*Math.PI/180;return (float)(-o.BaselineX*page.Width*Math.Sin(a)+o.BaselineY*page.Height*Math.Cos(a));}
 static EditObject Combine(List<EditObject> lines,SizeF page){var first=lines[0];RectangleF bounds=first.Bounds;var text=new StringBuilder();for(int i=0;i<lines.Count;i++){var o=lines[i];bounds=RectangleF.Union(bounds,o.Bounds);if(i>0&&text.Length>0){float gap=Along(o,page,first.Angle)-Along(lines[i-1],page,first.Angle);float step=first.DisplayFontSize*(first.Style==null?1.2f:first.Style.LineHeight);if(gap>step*1.8f)text.Append("\n\n");else if(!text.ToString().EndsWith("-"))text.Append(' ');}text.Append(o.Text.Trim());}var style=first.Style==null?new TextStyle{Size=first.DisplayFontSize,Ink=Color.FromArgb((int)first.Color)}:first.Style.Copy();style.Wrap=true;style.BoxWidth=Math.Abs(first.Angle)>3&&first.Style!=null?first.Style.BoxWidth:Math.Max(bounds.Width*page.Width,first.Style==null?0:first.Style.BoxWidth);if(Math.Abs(first.Angle)<3)bounds.Width=style.BoxWidth/page.Width;if(lines.Count>1&&first.Style==null)style.LineHeight=Math.Max(.8f,Math.Min(3,(lines[1].BaselineY-first.BaselineY)*page.Height/Math.Max(1,first.DisplayFontSize)));style.BlockKey=first.BlockKey??("VinsPDF.Block."+Guid.NewGuid().ToString("N"));return new EditObject{Id=first.Id,Kind=1,Bounds=bounds,Text=text.ToString(),Members=lines.SelectMany(o=>o.Ids).Distinct().ToArray(),FontSize=first.FontSize,DisplayFontSize=first.DisplayFontSize,Color=first.Color,Angle=first.Angle,BaselineX=first.BaselineX,BaselineY=first.BaselineY,Style=style,BlockKey=style.BlockKey,IsParagraph=true,Layer=first.Layer,Locked=lines.Any(o=>o.Locked)};}
 }
}
